// r25: FAL hosted sonuc URL'sini kucuk JSON metadata olarak tasir; binary olusturmaz.
const items = $input.all();
const reqs = $('Build_Fal_Req').all();

return items.map((item, index) => {
  const url = item.json?.images?.[0]?.url ?? item.json?.image?.url;
  if (!url) {
    const detail = item.json?.detail ?? item.json?.error ?? JSON.stringify(item.json).slice(0, 300);
    throw new Error('Item ' + index + ': fal yanitinda images[0].url yok. Yanit: ' + detail);
  }
  if (!(String(url).startsWith('https://') || String(url).startsWith('http://'))) {
    throw new Error('Item ' + index + ': fal hosted URL dondurmedi. url=' + String(url).slice(0, 100));
  }

  const meta = reqs[index]?.json ?? {};
  const mockupIndex = meta.prompt_index ?? index + 1;
  const loop = $('Loop_Files').first()?.json ?? {};
  const sourceBaseName = meta.source_base_name ?? String(loop.name || 'mockup').replace(/[.][^/.]+$/, '');
  let outputFolderId = meta.output_folder_id;
  try { if (!outputFolderId) outputFolderId = $('Resolve_Folder').first()?.json?.output_folder_id; } catch (e) {}

  return {
    json: {
      download_url: String(url),
      mockup_index: mockupIndex,
      source_file_name: meta.source_file_name,
      source_base_name: sourceBaseName,
      source_file_id: loop.id,
      output_folder_id: outputFolderId
    },
    pairedItem: { item: index }
  };
});

// r32: 0.86 doluluklu kaynaktan ikinci, sahne-bazli high-fill fiziksel metal masterini uretir.
// Yalniz M02/M12 bu hosted URL'i kullanir; mevcut 0.60 standard master akisi aynen devam eder.
function getDims(buf) {
  if (!buf || buf.length < 24) return { w: 0, h: 0 };
  if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4E && buf[3] === 0x47) return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
  if (buf[0] === 0xFF && buf[1] === 0xD8) {
    let pos = 2;
    while (pos + 9 < buf.length) {
      if (buf[pos] !== 0xFF) { pos++; continue; }
      let marker = buf[pos + 1];
      while (marker === 0xFF && pos + 1 < buf.length) { pos++; marker = buf[pos + 1]; }
      if (marker === 0xD8 || marker === 0xD9 || marker === 0x01 || (marker >= 0xD0 && marker <= 0xD7)) { pos += 2; continue; }
      if (pos + 4 > buf.length) break;
      const segLen = buf.readUInt16BE(pos + 2);
      if (marker >= 0xC0 && marker <= 0xCF && marker !== 0xC4 && marker !== 0xC8 && marker !== 0xCC) return { h: buf.readUInt16BE(pos + 5), w: buf.readUInt16BE(pos + 7) };
      pos += 2 + segLen;
    }
  }
  return { w: 1024, h: 1024 };
}
function masterSize(w, h) {
  if (!w || !h) { w = 1024; h = 1024; }
  const scale = 1024 / Math.max(w, h);
  const snap = (v) => Math.max(512, Math.min(1024, Math.round(v / 16) * 16));
  return { width: snap(w * scale), height: snap(h * scale) };
}
function stableSeed(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return Math.abs(h) % 2147483647;
}
const item = $input.first();
const j = $('If_Metal_Needs_Master').first()?.json ?? {};
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = item.binary?.data?.mimeType || 'image/png';
const dims = getDims(buf);
const prompt = `Photograph this laser-cut metal wall panel as a straight studio product shot: one continuous photograph of a plain, soft light-grey studio wall, the panel whole and centred with clear even margins on all four sides, its height about 60% of the frame. You are photographing the same object: every line weight, proportion, cut-out and outer silhouette exactly as in the source image. Every opening is cut clean through the sheet - the narrowest hairline slits and the slits inside solid areas alike - each a true hole with the wall showing through it. The metal covers exactly what it covers in the source image and no more; every other area is open wall, never filled in.

Scene: a plain studio wall in soft, even light from the upper left, no props and no furniture - only the panel, its soft shadow and the wall.

No mounting hardware: the silhouette is purely the design. The panel floats 1-2 cm off the wall and its shadow falls on the wall only: narrow, very soft, offset with the light.

Material: a thin steel sheet with a uniform commercial matte-black powder coat (#1C1C1C); its 3 mm paper-thin cut edge has exactly the same neutral-black tone as the face, and the finish is smooth at normal viewing distance with only a subtle, tight powder-coat microtexture visible in close-up, spatially uniform from edge to edge under the soft studio light.`;
const sourceBase = j.output_folder_name || String(j.name || '').replace(/\.[^/.]+$/, '');
return [{ json: {
  prompt,
  image_urls: ['data:' + mime + ';base64,' + buf.toString('base64')],
  image_size: masterSize(dims.w, dims.h),
  seed: stableSeed(sourceBase + '#12'),
  meta: j
}, pairedItem: { item: 0 } }];

// r32: keep the current 0.60 item for the standard master; prepare a separate 0.86 source.
const standard = $input.first();
const loop = $('Loop_Files').first()?.json ?? {};
const isPdf = String(loop.mimeType || '').toLowerCase() === 'application/pdf';
let source = standard;
if (isPdf) source = $('GDrive_Download').first();
if (!source?.binary?.data) throw new Error('r32 high-fill source binary is missing.');
return [{
  json: { ...(standard.json || {}), highfill_source_is_pdf: isPdf },
  binary: { data: source.binary.data },
  pairedItem: standard.pairedItem || { item: 0 }
}];

// r29: Stage-2 FAL istegini hazirlar. Onayli metal sahne oranlarini acik boyutla korur; diger hosted baskisiz metal kaynaklarini 1024 uzun kenarla sinirlar.
// Binary yalniz hosted kaynagi olmayan eski urun dallarinda, tek mockup dongusu icinde okunur.
function getDims(buf) {
  if (!buf || buf.length < 24) return { w: 0, h: 0 };
  if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4E && buf[3] === 0x47) {
    return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
  }
  if (buf[0] === 0xFF && buf[1] === 0xD8) {
    let pos = 2;
    while (pos + 9 < buf.length) {
      if (buf[pos] !== 0xFF) { pos++; continue; }
      let marker = buf[pos + 1];
      while (marker === 0xFF && pos + 1 < buf.length) { pos++; marker = buf[pos + 1]; }
      if (marker === 0xD8 || marker === 0xD9 || marker === 0x01 || (marker >= 0xD0 && marker <= 0xD7)) { pos += 2; continue; }
      if (pos + 4 > buf.length) break;
      const segLen = buf.readUInt16BE(pos + 2);
      if (marker >= 0xC0 && marker <= 0xCF && marker !== 0xC4 && marker !== 0xC8 && marker !== 0xCC) {
        if (pos + 9 > buf.length) break;
        return { h: buf.readUInt16BE(pos + 5), w: buf.readUInt16BE(pos + 7) };
      }
      pos += 2 + segLen;
    }
  }
  return { w: 0, h: 0 };
}

const MIN = 512, MAX = 2048;
function fitSize(w, h, hedefUzun) {
  if (!w || !h) { w = 1024; h = 1024; }
  let s = hedefUzun ? (hedefUzun / Math.max(w, h)) : Math.min(MAX / w, MAX / h, 1);
  let W = w * s, H = h * s;
  const up = Math.max(MIN / W, MIN / H, 1);
  W *= up; H *= up;
  const snap = (v) => Math.max(MIN, Math.min(MAX, Math.round(v / 16) * 16));
  return { width: snap(W), height: snap(H) };
}

function stableSeed(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return Math.abs(h) % 2147483647;
}

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const j = it.json || {};
  const sourceCandidate = String(j.fal_source_url || '');
  const hostedUrl = (sourceCandidate.startsWith('https://') || sourceCandidate.startsWith('http://')) ? sourceCandidate : '';
  let buf = null;
  let imageUrl = hostedUrl;

  if (!imageUrl) {
    const b = (it.binary && it.binary.data) ? it.binary.data : {};
    buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    const mime = b.mimeType || 'image/png';
    imageUrl = 'data:' + mime + ';base64,' + buf.toString('base64');
  }

  const m = /^([0-9]+)x([0-9]+)$/.exec(String(j.size || 'auto'));
  const src = m ? { w: +m[1], h: +m[2] } : (buf ? getDims(buf) : { w: 2048, h: 2048 });
  const idx = j.prompt_index ?? (i + 1);
  const baseSeed = stableSeed((j.source_base_name || '') + '#' + idx);
  const seedOffset = Number(j.fal_seed_offset) || 0;
  const finalSeed = ((baseSeed + seedOffset) % 2147483647 + 2147483647) % 2147483647;
  const requestedLong = Number(j.hedef_uzun) || 0;
  const falNegativePrompt = String(j.fal_negative_prompt || '').trim();
  // r27: Yalniz hosted baskisiz metal masteri; ayni-seed 2048/1024 A/B renk bantlarini 1024'te belirgin azaltti.
  const isHostedUnprintedMetal = !!hostedUrl && j.fal_source_kind === 'unprinted_metal_master' && (j.product_type === 'metal wall art' || j.product_type === 'metal revizyon');
  const explicitSceneSize = !!m && j.explicit_scene_size === true;
  const targetLong = explicitSceneSize
    ? 0
    : (isHostedUnprintedMetal ? Math.min(requestedLong || 1024, 1024) : requestedLong);
  const size = fitSize(src.w, src.h, targetLong);
  const appliedLong = explicitSceneSize ? Math.max(size.width, size.height) : targetLong;

  out.push({
    json: {
      prompt: j.prompts,
      image_urls: [imageUrl],
      image_size: size,
      seed: finalSeed,
      prompt_index: idx,
      source_file_name: j.source_file_name,
      source_base_name: j.source_base_name,
      output_folder_id: j.output_folder_id,
      product_type: j.product_type,
      requested_size: j.size ?? 'auto',
      measured_w: src.w,
      measured_h: src.h,
      requested_long: requestedLong,
      explicit_scene_size: explicitSceneSize,
      applied_long: appliedLong,
      source_kind: j.fal_source_kind || '',
      ...(falNegativePrompt ? { fal_negative_prompt: falNegativePrompt } : {})
    },
    pairedItem: { item: i }
  });
}
return out;

// ============================================================
//  Parse_JSON — SHAPE-DRIVEN ürün-önce mimarisi
//  Input artık TASARIM değil; Stage-1'de template'lerle üretilmiş ÜRÜN görselleridir.
//  Gelen item.binary içinde her shape için ürün(ler) bulunur:
//    product_<shape>      = PERSPEKTİFLİ template çıktısı (deliverable; sahnede kullanılmaz,
//                           Extract_Products ile klasöre yüklenir; düz yoksa sahnede yedek)
//    product_<shape>_duz  = DÜZ template çıktısı (SAHNE mockup'ları bundan üretilir)
//  Her shape için sahne kaynağı: düz varsa düz, yoksa perspektifli. Hiç yoksa shape atlanır.
// ============================================================

const inputItem = $input.first();
if (!inputItem) return [];
const inp = inputItem.json ?? {};

// Metadata: önce gelen item'dan, yoksa Loop_Files'tan (lineer akışta güvenli).
let loop = {};
try { loop = $('Loop_Files').first()?.json ?? {}; } catch (e) { loop = {}; }
const pick = (k) => (inp[k] ?? loop[k] ?? '');

const productType = pick('product_type');
const yon = pick('product_direction');
const variation = pick('variation');
const surfaceClause = pick('surface_clause');
const sourceFileName = pick('name');
const sourceBaseName = (pick('output_folder_name') || sourceFileName).replace(/\.[^/.]+$/, '');
let outputFolderId = inp.output_folder_id ?? loop.output_folder_id ?? '';
try { if (!outputFolderId) outputFolderId = $('Resolve_Folder').first()?.json?.output_folder_id ?? ''; } catch (e) {}

const productBins = inputItem.binary ?? {};

// Tüm olası shape'ler (Stage-1 ile aynı sıra/isim). Yeni shape eklemek için buraya ekle.
const SHAPES = ['yatay', 'dikey', 'panoramik', 'kare', 'yuvarlak'];

// product_direction / variation -> kanonik shape adı
function normShape(s) {
  s = String(s || '').toLowerCase();
  if (s.includes('yuvarlak') || s.includes('daire')) return 'yuvarlak';
  if (s.includes('yuksek') || s.includes('yüksek')) return 'yuksek_dikdortgen';
  if (s.includes('panoramik')) return 'panoramik';
  if (s.includes('dikey')) return 'dikey';
  if (s.includes('yatay')) return 'yatay';
  if (s.includes('kare')) return 'kare';
  return s;
}
const primaryShape = normShape(yon);

// ╔═══ DÜZENLENEBİLİR KURALLAR ═══╗
// Girdi NİHAİ ÜRÜNDÜR; oran/ölçü/crop zorlayan eski kurallar yok, tek kilit kuralı var.
const R_URUN_KILIT = `GİRDİDEKİ ÜRÜN KİLİTLİDİR: Sana verilen görsel, üretilmiş NİHAİ üründür. Üzerindeki tasarım, dış form, en-boy oranı, kadraj, baskı içeriği, renkler ve kompozisyon BİREBİR korunmalıdır. Ürünü kırpma, yeniden çerçeveleme, uzatma (extend/outpaint), esnetme, sıkıştırma, döndürme, yeniden çizme veya tasarımını değiştirme. Yeni motif, desen, yazı, arka plan deseni veya obje EKLEME. SADECE ürünün sahne içindeki yerleşimi, kamera açısı ve perspektifi değişebilir; ürünün kendisi sabittir. Üründeki mevcut cam yansıması/parıltısı da ürünün PARÇASIDIR ve girdideki haliyle korunur.`;

const R_CERCEVE = `ÇERÇEVE YOK: Ürüne çerçeve, kenarlık, pervaz, paspartu veya bordür EKLEME. Üründe zaten var olan ince cam kenarı dışında yeni bir sınır oluşturma.`;

const R_YANSIMA = `CAM YÜZEY (YANSIMA GİRDİYE SABİTLENMİŞTİR): Ürün parlak, cilalı camdandır ve girdi görselinde cam yüzeyin doğal yansıması/parıltısı ZATEN MEVCUTTUR — bu, doğru miktardır. Bu yansımayı GİRDİDEKİ HALİYLE koru: yeni yansıma EKLEME, mevcut yansımayı GÜÇLENDİRME/BÜYÜTME ve tamamen SİLME/MATLAŞTIRMA da yapma. Kamera açısı değiştiğinde yansıma yalnızca perspektife uygun şekilde konumlanabilir; kapladığı alan ve şiddeti girdidekiyle AYNI kalmalıdır. IŞIK KAYNAĞI DEĞİL (ZORUNLU): Ürün kendi başına bir ışık kaynağı değildir; yüzeyi veya kenarları KENDİLİĞİNDEN parlamamalı, ışımamalı veya arkadan aydınlatmalı ya da iç ışıklı görünmemelidir. Sahnedeki gerçek ışık kaynaklarından (lamba, pencere, gün ışığı vb.) gelen yansımalar dışında, üründen kaynaklanan hiçbir ek parlama, hale (glow) veya ışıma efekti EKLEME; tüm ışık dışarıdan camın üzerine düşüyormuş gibi görünmeli, üründen yayılıyormuş gibi görünmemelidir.`;

const R_KENAR = `İNCE KENAR (KÖŞE/KENAR ÇEKİMİ): Ürün 4mm temperli düz camdır, kâğıt kadar incedir. Profilden bakıldığında cam kenarı ince, tek, keskin ve cilalı bir çizgi gibi görünür; hafif yeşilimsi temper tonu olabilir. Ürünü kalın blok, levha, akrilik blok, pahlı veya çerçeveli gösterme. KENARDA IŞIK YOK: Cam kenarı boyunca kendinden ışıklı, tekdüze parlayan bir ışık şeridi/hattı veya kendiliğinden parlayan bir çizgi YOKTUR. Kenarda cilalı camın doğasından kaynaklanan parlak ışık şeritleri/parıltılar OLABİLİR (sahnedeki ışığın cilalı kenardan yansımasıyla oluşan doğal parıltı), ancak bu mutlaka bir YANSIMA gibi görünmelidir — kenarın kendi içinden gelen, tekdüze, sabit parlaklıkta bir aydınlatma elemanı gibi görünmemelidir. Ayrım: yansıma sahnedeki ışığa göre değişken/düzensiz parlar ve etrafındaki ışıkla tutarlıdır; kendinden ışıklı tekdüze görünüm ise sabit ve kendinden kaynaklı parlar — kesinlikle ikincisinden kaçın.`;

// TÜM ÜRÜN TÜRLERİ — ürünle bitişik ışıklandırma yasağı: ürüne değen/bitişik ışıklar
// ürünün parçasıymış gibi algılanıp yanıltıcı olduğundan hiçbir sahnede kullanılmaz.
const R_BITISIK_ISIK = `ÜRÜNE BİTİŞİK IŞIK ŞERİDİ YASAK (DAR KAPSAMLI): Bu yasak SADECE şunu kapsar: ürünün kenarına DEĞEN veya kenarı boyunca uzanan, kendinden parlayan FİZİKSEL bir aydınlatma şeridi/çubuğu — yani ürünün kenarına yapışık kendinden ışıklı bir aydınlatma şeridi, ışıklı bir hat, ışıklı profil çıtası veya ürünü çevreleyen arkadan aydınlatmalı bir ışık halkası. Bu tür kenara yapışık ışık hatları ürünün bir parçasıymış gibi algılanıp yanıltıcı olduğu için kullanılmaz. BUNUN DIŞINDAKİ HER TÜRLÜ AYDINLATMA SERBESTTİR: mutfak/banyo tavan aydınlatması, spot, sarkıt, lamba, pencere/gün ışığı ve dolap altı aydınlatma normal şekilde kullanılabilir; yeter ki ışık ürünün kenarına yapışık, kendinden parlayan bir şerit/çubuk oluşturmasın. BU KURAL YANSIMAYI, PARLAMAYI VE ORTAM AYDINLIĞINI ASLA KISITLAMAZ (ÖNCELİK YANSIMADADIR): Bu kural hiçbir şekilde ürünün cam yüzeyindeki ışık yansımalarını, yüzeydeki parıltıları veya sahnenin genel aydınlığını azaltmaz/zayıflatmaz/silmez; sahne bol ve doğal ışık almalı, ürünün yüzeyinde belirgin ve doğal bir ışık yansıması bulunmalıdır. Herhangi bir çelişki halinde ürünün yüzeyinde belirgin ışık yansıması olması bu yasaktan ÖNCELİKLİDİR — kararsız kalınırsa yansımayı KORU, yalnızca varsa kenara yapışık ışık şeridini çıkar.`;

const ekMetin = `Do not add any dots, screws, caps, standoffs, mounting hardware, holes, or corner details on the product. Mockupa herhangi bir metin veya çizim ekleme.` + '\n\n' + R_BITISIK_ISIK;
const ekMetinMetal = `Every laser-cut opening stays empty see-through negative space with the wall visible behind it. The product's own design is the only artwork in the frame.`;

// ── Kural paketleri ──
const CAM_KURALLARI       = R_URUN_KILIT + '\n\n' + R_CERCEVE + '\n\n' + R_YANSIMA;
const CAM_KENAR_KURALLARI = R_URUN_KILIT + '\n\n' + R_KENAR + '\n\n' + R_CERCEVE + '\n\n' + R_YANSIMA;
// TEZGAH — alt kenar tezgaha oturur: tüm tezgah sahnelerinde ürün ile tezgah yüzeyi
// arasında boşluk olmamalı (olursa fark edilmeyecek kadar minimum).
const R_TEZGAH_ALT_OTURMA = `ALT KENAR TEZGAHA OTURUR (ZORUNLU): Ürün bir tezgah arası paneldir; ALT KENARI, altındaki tezgah/lavabo tezgahı yüzeyiyle BİTİŞİK olmalıdır. Ürün ile tezgah yüzeyi arasında boş duvar şeridi BIRAKMA; teknik bir montaj payı görünecekse bile fark edilmeyecek kadar MİNİMUM olmalıdır. Ürünü tezgahtan yukarıda, duvar ortasında havada asılıymış gibi GÖSTERME; alt kenarın tezgah yüzeyiyle buluştuğu hat sahnede net ve doğal görünmelidir.`;
const R_TEZGAH_YANSIMA = `CAM YÜZEY YANSIMASI (TEZGAH — ZORUNLU, EN YÜKSEK ÖNCELİK): Ürün parlak, cilalı camdan bir mutfak tezgah arası panelidir; mutfak/banyo ortamındaki gerçek ışık kaynaklarından (pencere ışığı, tavan ve spot aydınlatması, gün ışığı) yüzeyine düşen NET ve BELİRGİN bir ışık yansıması/parıltısı MUTLAKA görünmelidir. Ürünün cam yüzeyi ASLA tamamen mat, sönük veya yansımasız görünmemeli; her tezgah sahnesinde yüzeyde fark edilir, doğal bir parlama/yansıma bulunmalıdır. Bu yansıma sahnedeki ışıkla tutarlı, yumuşak ve fiziksel olarak inandırıcı olmalı (ortam yansımaları ve yüzeydeki hafif parıltılar); tasarımı okunamaz kılacak kadar güçlü veya yüzeyi bembeyaz yıkayacak kadar aşırı OLMAMALI, ama silik/yok denecek kadar zayıf da OLMAMALIDIR. ÖNCELİK: Bu kural, ürünün yüzey yansımasını kısıtlayan, zayıflatan veya girdideki haline sabitleyen diğer TÜM ifadelerin ÜZERİNDEDİR; herhangi bir çelişki durumunda yüzeyde belirgin ışık yansıması olması önceliklidir. Yansıma yalnızca sahnedeki dış ışık kaynaklarından gelmeli; ürün kendi başına ışık yaymamalı, kenarları veya yüzeyi arkadan aydınlatmalı ya da iç ışıklı görünmemelidir.`;
const TEZGAH_KURALLARI    = R_URUN_KILIT + '\n\n' + R_CERCEVE + '\n\n' + R_TEZGAH_YANSIMA + '\n\n' + R_TEZGAH_ALT_OTURMA;
const CAM_KURALLARI_YUVARLAK       = R_URUN_KILIT + '\n\n' + R_CERCEVE + '\n\n' + R_YANSIMA;
const CAM_KENAR_KURALLARI_YUVARLAK = R_URUN_KILIT + '\n\n' + R_KENAR + '\n\n' + R_CERCEVE + '\n\n' + R_YANSIMA;

// TEZGAH KARE — girdi zaten TAM KARE'ye kırpılmış bir tasarımdır; sahnedeki duvar alanı
// kareden farklı orana sahip olsa bile ürün ASLA dikdörtgene esnetilmemeli/kırpılmamalı.
const R_TEZGAH_KARE_KILIT = `GİRDİDEKİ KARE TASARIM ASLA DEĞİŞTİRİLMEZ: Sana verilen görsel, önceden TAM KARE (1:1) orana kırpılmış, baskıya hazır bir tasarımdır. Bu tasarımı ASLA yeniden kırpma, kenarlarından kesme, herhangi bir yönde uzatma/genişletme (extend/outpaint) yapma veya farklı bir en-boy oranına getirme; ürün sahnede HER ZAMAN tam kare (1:1) formunda kalmalıdır. Sahnedeki duvar alanı kareden farklı bir oranda görünse bile, ürünün kendisini o alanı doldurmak için dikdörtgene DÖNÜŞTÜRME veya ESNETME; ürün her koşulda kare kalmalı, gerekirse etrafında sade duvar boşluğu görünsün. SAHNE TUTARLILIĞI (ÇOK ÖNEMLİ): Sahnedeki dolap, cihaz veya mobilyaların yerleşimi ürünün KARE olmasıyla görsel olarak tutarlı olmalıdır; ürünün etrafında, sanki ürün daha geniş veya daha uzun olmalıymış hissi verecek boş/doldurulmamış fazladan bir duvar alanı BIRAKMA. Ürünün bittiği yerde ilişkili olduğu nesnenin (lavabo, tezgah, cihaz vb.) kenarı da bitmelidir; ürün görsel olarak eksik kalmış veya genişletilmeye ihtiyacı varmış gibi görünmemelidir.`;
const TEZGAH_KARE_KURALLARI = TEZGAH_KURALLARI + '\n\n' + R_TEZGAH_KARE_KILIT;

// TEZGAH YATAY/PANORAMİK — panel formu ve oran kilidi: ürün duvar kaplaması gibi duvarın
// tamamına yayılmamalı, davlumbaz/dolap etrafında bölünmemeli, oranı girdiyle aynı kalmalı.
const R_TEZGAH_PANEL_KILIT = `PANEL FORMU VE ORAN KİLİDİ (EN KRİTİK KURAL): Sana verilen görsel, kenarları belli, SABİT en-boy oranına sahip TEK PARÇA dikdörtgen bir cam paneldir; sahnede de girdideki oranla BİREBİR AYNI oranda görünmelidir. Ürünü duvardaki boşluğu doldurmak için ASLA genişletme, uzatma (extend/outpaint), tasarımı yeni desenle devam ettirme, esnetme, sıkıştırma veya kırpma. Girdideki oran neyse sahnedeki oran da odur: yatay dikdörtgen bir paneli ince-uzun panoramik bir şerit gibi GÖSTERME; panelin sahnedeki genişlik/yükseklik oranı girdiden farklıysa bu KRİTİK BİR HATADIR. PANEL DUVAR KAPLAMASI DEĞİLDİR: Panel duvarın tamamını kaplamaz; panelin kenarları sahnede net görünmeli, SOL-SAĞ uçlarının ve ÜST kenarının ötesinde sade duvar/fayans devam etmelidir (ALT kenar duvara değil, tezgah yüzeyine oturur). TEK VE KESİNTİSİZ: Panel davlumbaz, dolap, raf, pencere veya başka bir nesnenin etrafını dolaşacak şekilde parçalara BÖLÜNMEZ, biçimi bozulmaz ve bir nesnenin arkasında devam ediyormuş gibi GÖSTERİLMEZ; hiçbir nesne panelin üzerine binip onu kesmemelidir. SAHNE PANELE UYDURULUR (panel sahneye değil): Ocak/eviye/davlumbaz/dolap yerleşimini panelin girdideki oranına uygun kur — panelin genişliği altındaki ocak/eviye bölümüyle orantılı olmalı; davlumbaz kullanılacaksa tamamen panelin ÜST KENARININ ÜZERİNDE kalmalı; panelin etrafında, panel daha genişmiş ya da alanı dolduramamış hissi verecek boş duvar alanı BIRAKMA.`;
const TEZGAH_PANEL_KURALLARI = TEZGAH_KURALLARI + '\n\n' + R_TEZGAH_PANEL_KILIT;

// TEZGAH PANORAMİK — panel kilidinin panoramik varyantı: oran/tek-parça kuralları aynı,
// ancak panel havada asılı bir tablo gibi DEĞİL, alt kenarı tezgaha oturan, üst kenarı
// dolap hattına dayanan gerçek bir backsplash gibi monte edilmiş görünmeli.
const R_TEZGAH_PANORAMIK_KILIT = `PANEL FORMU VE ORAN KİLİDİ (EN KRİTİK KURAL): Sana verilen görsel, SABİT geniş panoramik en-boy oranına sahip TEK PARÇA dikdörtgen bir cam backsplash panelidir; sahnede de girdideki oranla BİREBİR AYNI oranda görünmelidir. Ürünü duvardaki boşluğu doldurmak için ASLA genişletme, uzatma (extend/outpaint), tasarımı yeni desenle devam ettirme, esnetme, sıkıştırma veya kırpma. TEK VE KESİNTİSİZ: Panel davlumbaz, dolap, raf, pencere veya başka bir nesnenin etrafını dolaşacak şekilde parçalara BÖLÜNMEZ, biçimi bozulmaz ve bir nesnenin arkasında devam ediyormuş gibi GÖSTERİLMEZ; hiçbir nesne panelin üzerine binip onu kesmemelidir. AMACINA UYGUN MONTAJ (HAVADA DURMAZ): Bu ürün bir BACKSPLASH'tir; duvarın ortasında havada asılı bir tablo gibi GÖSTERİLMEZ. Panelin ALT KENARI tezgah yüzeyine OTURMALI (tezgahla bitişik), ÜST KENARI üst dolapların/davlumbaz hattının alt hizasına dayanabilir; panelin altında veya üstünde geniş boş duvar şeridi BIRAKMA. Yalnızca SOL ve SAĞ uçlarında panelin bittiği yer görünmeli ve uçların ötesinde sade duvar devam etmelidir; panel duvarın tamamını da KAPLAMAMALI. SAHNE PANELE UYDURULUR (panel sahneye değil): Tezgah/ocak/dolap yerleşimini panelin girdideki geniş oranına uygun kur — panelin genişliği altındaki tezgah/ocak bölümüyle orantılı olmalı; paneli sığdırmak için oranını değiştirmek KRİTİK BİR HATADIR.`;
const TEZGAH_PANORAMIK_KURALLARI = TEZGAH_KURALLARI + '\n\n' + R_TEZGAH_PANORAMIK_KILIT;

const T = (s) => s.trim();

// ============================================================
//  CAM (glass wall art) — PRIMARY (ana shape) sahneleri: 10 genel + 1 kenar makro = 11
