function buildGlassPrimary(shape) {
  const kurallari      = (shape === 'yuvarlak') ? CAM_KURALLARI_YUVARLAK       : CAM_KURALLARI;
  const kenarKurallari = (shape === 'yuvarlak') ? CAM_KENAR_KURALLARI_YUVARLAK : CAM_KENAR_KURALLARI;
  return [

  T(`${kurallari}\n\nSAHNE: Bu bir ${productType}. Şık, modern bir iç mekanda, mekânın dekorasyonuyla uyumlu, duvarda net görünen bir mockup tasarla.`),
  T(`${kurallari}\n\nSAHNE: Bu bir ${productType}. Dekoratif ve profesyonel görünen bir iç mekan duvarı; arka plan sade, ürün ön planda.`),
  T(`${kurallari}\n\nSAHNE: Bu bir ${productType}. Bir kişinin elinde tutarken çekilmiş bir mockup; sadece ürün değil tutan insan da görünsün, gerçekçi fiziksel ölçekte.`),
  T(`${kurallari}\n\nSAHNE: Bu bir ${productType}. Bir kişi tarafından duvara asılırken görünen, doğal ve profesyonel ürün sunumu hissi veren bir mockup.`),
  T(`${kurallari}\n\nSAHNE: Bu bir ${productType}. Doğrudan asılı değil; bir yere veya duvara hafifçe dayalı durduğu, dekoratif bir obje gibi alternatif bir mockup.`),
  T(`${kurallari}\n\nSAHNE: Bu bir ${productType}. Görselin tam merkezinde, tüm odak üründe; mekânın ferahlığını yansıtan aydınlık bir mockup.`),
  T(`${kenarKurallari}\n\nSAHNE: Bu bir ${productType}. Yalnızca ürünün bir köşesini ve ince cam kenarını gösteren çok yakın bir makro (close-up) mockup oluştur; profesyonel ürün makro fotoğrafı, hafif 3/4 yan açı, sığ alan derinliği ve net odak. Kadrajda ürünün tamamı değil, yalnızca köşe ve ince cam profili olsun.`)
  ];
}

