const R_CANVAS_KILIT = `GİRDİDEKİ TASARIM KİLİTLİDİR: Sana verilen görsel, baskıya hazır MASTER tasarımdır. Aynı shape'in tüm sahnelerinde tasarımın görünen kısmı BİREBİR AYNI kalmalıdır. Tasarımı kırpma, yeniden çerçeveleme (reframe), esnetme, sıkıştırma, döndürme veya yeniden çizme; yeni motif, desen, yazı veya obje EKLEME. SADECE kamera açısı, çerçeve varlığı/rengi ve sahne (mekân/ışık) değişebilir; tasarımın kendisi sabittir.`;

const R_CANVAS_DOKU = `TUVAL DOKUSU (ZORUNLU): Ürün gerçek bir gerilmiş tuval (stretched canvas) baskıdır; yüzeyde dokuma kumaş dokusu (canvas weave texture) HER ÇEKİMDE belirgin olmalıdır — sadece yakın/makro çekimlerde değil, normal ve orta mesafeli genel sahnelerde de ince diyagonal dokuma iplik deseni fark edilebilir olsun. Yüzey mat ve hafif kabartılıdır; ışığı düzgün/eşit yansıtmaz, dokumanın girinti çıkıntılarına göre hafif düzensiz (uneven) bir parlaklık/gölgelenme oluşur. Yüzey ASLA düz poster, parlak fotoğraf kâğıdı, cam, pürüzsüz plastik veya dümdüz/pürüzsüz bir baskı gibi görünmesin; mutlaka tuval dokusu hissedilsin. DOKU ÖLÇEĞİ (ÜST SINIR): Doku HER ZAMAN ince ve sık dokuma olmalıdır — gerçek, kaliteli pamuklu/keten tuval bezine (fine canvas duck) benzer incelikte. Makro/yakın çekimlerde bile iplikler kalın, iri veya seyrek görünmemeli; çuval bezi (burlap/jute), hasır veya örgü sepet gibi kaba/abartılı bir dokuma KESİNLİKLE gösterilmemelidir.`;

const R_CANVAS_CERCEVE_YOK = `ÇERÇEVE YOK: Düz gerilmiş tuval (stretched canvas), çerçevesiz, kenarları gallery-wrap şeklinde sarılı. Tuvale çerçeve, pervaz, paspartu veya bordür EKLEME.`;

function R_CANVAS_CERCEVE(renk) {
  return `İNCE FLOATING FRAME (${renk}): Tuval ile çerçeve arasında ince bir boşluk bırakan, ince kesitli ${renk} renkte bir floating (asma) çerçeve kullan. Çerçeve kalın veya klasik pervaz gibi görünmesin; sade, modern, ince bir asma çerçeve olsun. ÇERÇEVE TUVALİ SARMAZ (ÇOK ÖNEMLİ): Çerçeve tuvalin kenarını SARMAZ ve tuvalle KAYNAŞMIŞ, TEK PARÇA kalın bir kenar/rim OLUŞTURMAZ; çerçeve tuvalden ayrı, tuvalin arkasında duran ince bir halka/çıtadır ve tuval ile çerçeve arasında gölgeli, net bir boşluk (floating gap) HER ZAMAN görünür olmalıdır. Çerçeve KESİNLİKLE bir tepsi, tabak, saat kadranı kenarı veya lazy susan gibi kalın ve tuvalle bütünleşik görünmemelidir. METALİK YÜZEY: Çerçeve belirgin şekilde metalik bir yüzeye/parıltıya sahip olmalı (parlak fırçalanmış metal / brushed metal hissi, ışığı yumuşak ama net bir parlaklıkla yansıtan bir yüzey); aşırı aynasal veya krom gibi ışıldamasın, ama mat boyalı ahşap gibi de görünmesin. Çerçevenin rengi (${renk}) soluk, donuk veya griye kaçan bir ton OLMAMALI; doygun, canlı (vibrant, saturated) ve net bir ${renk} tonu olarak görünmelidir. ÇERÇEVE-TUVAL YÜKSEKLİK HİZASI (ZORUNLU, EN KRİTİK KURAL): Çerçevenin yan derinliği (profildeki yüksekliği) ile tuvalin yan derinliği (profildeki yüksekliği) BİRBİRİNE EŞİT olmalı ve ikisi de çok ince kalmalıdır (tuvalin ön yüz genişliğinin/çapının en fazla %2-3'ü). Çerçeve tuvalden DAHA KISA/İNCE OLAMAZ; tuval çerçevenin üstünden veya kenarından ASLA taşmaz/sarkmaz — profilden veya köşeden bakıldığında tuvalin üst ve alt sınırı çerçevenin üst ve alt sınırıyla TAM HİZALI olmalıdır. Tuval çerçeveden daha kalın/yüksek görünüyorsa bu KRİTİK BİR HATADIR.`;
}

const R_CANVAS_KENAR = `KENAR (MACRO/GALLERY-WRAP): Tuvalin yalnızca kenarının bir bölümünü çok yakından gösteren makro bir çekim; asıl odak gerilmiş kumaş dokusu ve kenara sarılan tasarımdır (gallery-wrap). İNCELİK (EN ÖNEMLİ KURAL): Tuval ÇOK İNCEDİR; yan derinlik, tuvalin ön yüz genişliğinin/çapının EN FAZLA %2-3'ü kadardır ve kadrajda yalnızca DAR BİR ŞERİT olarak görünür — görüntüdeki en ince unsurlardan biri olmalıdır. Yan derinlik ön yüz kadar dikkat çekiyorsa veya ön yüzün belirgin bir parçası gibi geniş duruyorsa bu YANLIŞTIR; derinliği vurgulama, abartma, büyütme. KENAR KESİTİ DÜZ VE KESKİN (ÇOK ÖNEMLİ): Tuvalin yan derinlik kesiti (profili) DÜZ BİR DUVAR gibidir ve ön yüzle KESKİN 90° bir açıyla birleşir — tıpkı bir dikdörtgen prizmanın kenarı gibi. Kenar KESİNLİKLE yuvarlatılmış, yastıklanmış (bombeli/pillow), şişkin veya dairesel bir kesite sahip OLMAMALIDIR; yandan bakıldığında ince, düz ve keskin köşeli bir bant görünmelidir. NOT: Yuvarlak üründe yalnızca dış çevre hattı daireseldir; buna karşılık yan derinlik kesiti yine düz duvar + keskin 90° köşe olmalıdır. Tuval veya (varsa) çerçeve KESİNLİKLE kalın bir blok, kutu, tepsi, tabak veya lazy susan kenarı gibi görünmemelidir; derinlik, tuvalin çapına/genişliğine kıyasla çok ince kalmalıdır. FORMA UYGUN KENAR (ÇOK ÖNEMLİ): Ürünün dış formu köşeli (kare/dikdörtgen) ise gerçek, keskin 90° bir köşe gösterilebilir. Ürün YUVARLAK ise ürünün KÖŞESİ YOKTUR — bu durumda gösterilen kenar, dairenin kesintisiz, düzgün ve tutarlı bir kavisli parçası olmalıdır; düz bir kenar, köşe veya fiziksel olarak tutarsız/bozuk bir hat KESİNLİKLE gösterilmemelidir.`;

const R_CANVAS_ASILI = `YERLEŞİM: Ürün düz biçimde duvara ASILI (monte) olmalı. Ürünü bir duvara, zemine, rafa, sehpaya, koltuğa veya herhangi bir yüzeye YASLANMIŞ/DAYALI GÖSTERME. FİZİKSEL DERİNLİK (ZORUNLU): Tuval duvardan hafifçe (birkaç santim) uzakta, gergi çerçevesi üzerinde durur; kamera açısına göre tuvalin kenarında yalnızca ÇOK İNCE bir yan profil çizgisi görünebilir (zorunlu değil); görünüyorsa bu profil, tuvalin ön yüz genişliğinin EN FAZLA %2-3'ü kadar DAR BİR ŞERİTTİR — asla daha geniş değil. Bu yan profil DÜZ bir duvar gibi olup ön yüzle KESKİN 90° açıyla birleşir (dikdörtgen prizma kenarı), yuvarlatılmış/yastık gibi bombeli OLMAMALI — kalın bir kutu, panel, tepsi, tabak veya masif blok gibi de ASLA görünmemeli. Derinlik/3B hissi esas olarak GÖLGEYLE verilir: tuval, duvar üzerine hemen altına/etrafına yumuşak, gerçekçi bir temas gölgesi (contact shadow) düşürmelidir. Ön yüz sahnenin ışık kaynağına göre yönlü ışık alsın; yüzeyin tamamı düzgün/eşit aydınlanmış, gölgesiz, düz bir görsel gibi durmasın — tuval duvara yapıştırılmış bir resim değil, duvardan hafifçe kabaran fiziksel bir obje gibi görünmelidir.`;

// Yuvarlak canvas: dış form DAİRE olmalı (kare/dikdörtgen değil).
const R_CANVAS_YUVARLAK_FORM = `DIŞ FORM DAİRE (ÇOK ÖNEMLİ): Bu ürün YUVARLAK bir tuvaldir; tuvalin kendisi tam bir DAİREDİR — dış hatları çember biçimindedir. Kesinlikle KARE veya DİKDÖRTGEN bir tuval gösterme; köşe YOK. Yuvarlak gergi çerçevesi üzerine gerilmiş dairesel tuval baskı; kenarı da dairesel gallery-wrap. Tasarımın dairenin dışında kalan köşeleri ürünün parçası değildir, sahne arka planına karışır.`;

const R_CANVAS_PANORAMIK_FORM = function(oran){ return `DIŞ FORM ULTRA-GENİŞ PANORAMİK (${oran}) (ÇOK ÖNEMLİ): Bu ürün ${oran} en-boy oranında ULTRA-GENİŞ panoramik bir tuvaldir; ürünün dış sınırları bu orana BİREBİR uymalıdır — genişlik yükseklikten çok daha fazladır. Ürünü ASLA normal/standart bir manzara oranına (ör. 3:2, 4:3, 16:9) normalize etme, daha az geniş gösterme, sıkıştırma, esnetme veya farklı bir orana getirme; sahnede HER ZAMAN ${oran} ultra-geniş kalmalıdır. GİRDİDEKİ TASARIMIN TAMAMI GÖRÜNMELİ (ÇOK ÖNEMLİ): Sana verilen master tasarımın HER detayı çıktıda eksiksiz görünmelidir; tasarımı kenarlarından KIRPMA, yeniden çerçeveleme (reframe) yapma veya herhangi bir kısmını kadraj dışında bırakma. TUVAL DUVARA YAPIŞIK GÖRÜNMEMELİ: Ürün gerçek bir gerilmiş panoramik tuval (stretched canvas) gibi görünmeli; düz bir poster veya duvar kâğıdı gibi değil. SAHNE TUTARLILIĞI (ÇOK ÖNEMLİ): Sahnedeki mimari/mobilya yerleşimi ürünün ${oran} ULTRA-GENİŞ olmasıyla mantıksal olarak tutarlı olmalıdır. Ürünü, genişliğini doğal olarak taşıyabilecek uzun ve yatay bir duvar alanına yerleştir (örneğin geniş bir kanepenin veya yatağın baş ucu üstünde yatay bir bant olarak, uzun bir konsol/yemek masası üstünde ya da uzun bir koridor/merdiven duvarında). KADRAJ KARE (1:1) (ÇOK ÖNEMLİ): Çıktı kadrajı KAREDİR; ${oran} ultra-geniş ürün bu karenin İÇİNE yerleştirilir ve doğal olarak üstünde/altında bir miktar duvar/oda boşluğu kalır — bu NORMAL ve BEKLENENDİR. Bu boşluğu doldurmak için ürünü büyütme, dikey olarak uzatma veya yatay olarak genişletme; ürün kareyi doldurmak ZORUNDA DEĞİLDİR. Ürünün en-boy oranı her koşulda tam ${oran} kalmalı; ürün ASLA ${oran}'dan daha geniş veya daha kare görünmemeli.`; };

