  8: T(`${CANVAS_KURALLARI_DUZ}\n\n${R_CANVAS_ASILI}\n\nSAHNE: Bu bir tuval baskı. Ürün DUVARDA ASILIDIR ve tam karşıdan, ürünün TAMAMI ve tüm genişliği eksiksiz görünecek şekilde çerçevesiz gerçekçi bir mockup oluştur. Yalnızca kenarı veya köşeyi gösteren makro/yakın kadraj KULLANMA; panoramik tasarımın bütünü görünür olmalı.`),
  10: T(`${CANVAS_KURALLARI_DUZ}\n\n${R_CANVAS_ASILI}\n\nSAHNE: Bu bir tuval baskı. Bol gün ışığı alan bir merdiven boşluğunun duvarında, çerçevesiz düz gerilmiş tuval olarak asılı gerçekçi bir mockup; ürün tam karşıdan (düz önden) ve ürünün TAMAMI ile tüm genişliği net görünecek şekilde çerçevelensin. Ürünü yandan/açılı, eğik veya genişliğini kısaltan (foreshortening) mimari bir perspektiften GÖSTERME.`)
};

// Master -> slot atama tablosu (product_direction'a göre).
function canvasEmit(bins, dir) {
  const d = String(dir || '').toLowerCase();
  const out = [];
  if (d.includes('yuvarlak')) {
    // Yuvarlak: dış form DAİRE zorunlu -> her slota round-form kurali eklenir.
    // Ayrıca yuvarlak canvas'ta çerçevesiz (stretched-only) seçenek YOK: tüm sahneler çerçeveli olmalı,
    // ve beyaz çerçeve yerine gümüş/altın rotasyonu kullanılır.
    const bin = bins['master_yuvarlak'] ?? bins['data'];
    if (!bin) return out;
    const roundColors = ['gümüş', 'altın'];
    let roundColorIdx = 0;
    const nextRoundColor = () => roundColors[roundColorIdx++ % roundColors.length];
    for (const slot of canvasSlots) {
      let text = slot.id === 8 ? CANVAS_SAHNE_8_YUVARLAK_OZEL : slot.text;
      if (text.includes(R_CANVAS_CERCEVE_YOK)) {
        text = text.replace(R_CANVAS_CERCEVE_YOK, R_CANVAS_CERCEVE(nextRoundColor()));
      } else if (text.includes(R_CANVAS_CERCEVE_BEYAZ_TEXT)) {
        text = text.replace(R_CANVAS_CERCEVE_BEYAZ_TEXT, R_CANVAS_CERCEVE(nextRoundColor()));
      } else if (text.includes(R_CANVAS_KENAR)) {
        text = text.replace(R_CANVAS_KENAR, R_CANVAS_KENAR + '\n\n' + R_CANVAS_CERCEVE(nextRoundColor()));
      }
      out.push({ shape: 'yuvarlak', text: R_CANVAS_YUVARLAK_FORM + '\n\n' + text, bin });
    }
  } else if (d.includes('panoramik')) {
    const binA = bins['master_panoramik_40x20'];
    const binB = bins['master_panoramik_60x20'];
    const mapA = [1, 2, 5, 8, 9];
    const mapB = [3, 4, 6, 7, 10];
    if (binA) for (const id of mapA) { const s = canvasSlots.find(x => x.id === id); const t = (id === 8) ? s.text : (PANO_OVERRIDES[id] ?? s.text); const pre = (id === 8) ? '' : (R_CANVAS_PANORAMIK_FORM('2:1') + '\n\n'); out.push({ shape: 'panoramik_40x20', text: pre + t, bin: binA, size: '1024x1024' }); }
    if (binB) for (const id of mapB) { const s = canvasSlots.find(x => x.id === id); const t = PANO_OVERRIDES[id] ?? s.text; out.push({ shape: 'panoramik_60x20', text: R_CANVAS_PANORAMIK_FORM('3:1') + '\n\n' + t, bin: binB, size: '1024x1024' }); }
  } else {
    // yatay / dikey: ana master 8 sahne (1,2,3,4,5,7,9,10), kare master 2 sahne (6,8)
    const mainKey = d.includes('dikey') ? 'master_dikey' : 'master_yatay';
    const mainBin = bins[mainKey];
    const kareBin = bins['master_kare'];
    const mainSlots = [1, 2, 3, 4, 5, 7, 9, 10];
    const kareSlots = [6, 8];
    if (mainBin) for (const id of mainSlots) { const s = canvasSlots.find(x => x.id === id); out.push({ shape: d.includes('dikey') ? 'dikey' : 'yatay', text: s.text, bin: mainBin }); }
    if (kareBin) for (const id of kareSlots) {
      const text = id === 8 ? CANVAS_SAHNE_10_YATAYDIKEY_OZEL : (id === 6 ? CANVAS_SAHNE_6_KARE_OZEL : canvasSlots.find(x => x.id === id).text);
      out.push({ shape: 'kare', text, bin: kareBin });
    }
  }
  return out;
}

// ============================================================
//  WOOD PRINT (tahta baski) — canvas ile AYNI master mimarisi; yalnizca yuzey kurallari tahta.
//  Fiziksel fark: tuval kumas dokusu YOK; tasarim MAT bir AHSAP PANEL yuzeye BASILIDIR (gercek yagliboya degil).
//  Sahne iskeleti canvas ile ayni (karsidan, cerceveli, ~30 aci, makro, elde, kenar);
//  yalnizca nispeten onemsiz 9-10. sahneler (okuma kosesi / merdiven) tazelendi.
//  Cerceve paleti: siyah, beyaz, altin, gumus, antrasit -> her yon ciktisinda 5 renk de en az 1 kez.
//  Tasarim kilidi R_CANVAS_KILIT ile ortaktir (urun-notrdur: "baskiya hazir MASTER tasarim").
// ============================================================
const R_TAHTA_DOKU = `YUZEY (ZORUNLU): Urun, tasarimin DUZ ve sert ince bir panel uzerine basildigi MAT bir sanat baskisidir; yuzey puruzsuz ve tamamen mattir. Yuzeyde hicbir doku, damar, elyaf, dokuma veya malzeme deseni HISSEDILMEZ; parlak fotograf kagidi, cam, akrilik veya parlak plastik gibi de GORUNMEZ. Tasarim her zaman net, keskin ve baskindir; yuzeye ekstra doku, desen veya malzeme gorunumu EKLEME. YUZEY TAMAMEN MATTIR (COK ONEMLI): yuzeyde HICBIR isik yansimasi, parlama, specular highlight, parlak leke veya parlak/saten/cam gibi gorunum OLMAMALIDIR; cam, akrilik, cilali veya lamine parlak yuzey gibi ASLA gorunmez. Isik yuzeye vurdugunda parlamaz, yalnizca yumusakca ve esit dagilir (tam diffuse/mat); yansimalar tasarimi asla okunaksiz yapmaz.`;

const R_TAHTA_CERCEVE_YOK = `INCE FLOATING FRAME (notr - ince siyah veya koyu-notr ton): Baski, COK INCE ve DAR profilli (yaklasik bir kalem kalinligi kadar), sade ve modern bir floating (asma) cerceve icindedir. CERCEVE BASKIYI TAM CEVRELER: cerceve, baskinin dis kenarini dort taraftan cevreler; baski cercevenin disina TASMAZ veya kenarindan cikmaz; baski ile cerceve arasinda ince, esit, golgeli bir bosluk her kenarda gorunur. Cerceve KESINLIKLE kalin, genis veya klasik/oymali pervaz gibi OLMAMALIDIR; ince, yassi, mat bir cita gibidir. Renk mat siyah veya kompozisyona uyan koyu-notr bir tondur.`;

function R_TAHTA_CERCEVE(renk){ return `INCE FLOATING FRAME (${renk}): Baski, ${renk} renkte, COK INCE ve DAR profilli (yaklasik bir kalem kalinligi kadar), sade ve modern bir floating (asma) cerceve icindedir. CERCEVE BASKIYI TAM CEVRELER (COK ONEMLI): cerceve, baskinin dis kenarini dort taraftan tam cevreler; baski cercevenin disina TASMAZ, kenarindan cikmaz ve cerceveyi asmaz. Baski ile cerceve arasinda ince, esit, golgeli bir bosluk (floating gap) her kenarda gorunur. Cerceve KESINLIKLE kalin, genis, hantal veya klasik/oymali pervaz gibi OLMAMALIDIR; ince, yassi, mat bir cita gibidir. ${renk} tonu net ve dogru gorunur, soluk veya donuk olmaz. ALTIN veya GUMUS ise fircalanmis mat-metalik (asiri aynasal/krom degil); diger renklerde mat boyali duz bir yuzeydir.`; }

const R_TAHTA_KENAR = `YAKIN PLAN (DETAY): Duvarda asili baskinin bir kosesini/kenarini yakindan gosteren makro bir cekim; kadrajda ince floating cerceve, cerceve ile baski arasindaki golgeli bosluk ve baskinin kenari birlikte net gorunur. Cerceve COK INCE ve DAR profilli, mat, sade ve moderndir; kalin veya klasik pervaz gibi OLMAMALIDIR. Baskinin kenari temiz ve keskindir; yuzey duz ve mattir, uzerinde doku/desen YOKTUR. Cerceve baskiyi tam cevreler; baski cercevenin disina tasmaz. Odak, tasarimin detayinin ve ince cercevenin netligidir.`;

const R_TAHTA_ASILI = `YERLESIM: Urun duz bicimde duvara ASILI (monte) olmalidir; bir duvara, zemine, rafa, sehpaya veya mobilyaya YASLANMIS/DAYALI GOSTERME. FIZIKSEL DERINLIK (ZORUNLU): Cerceveli baski duvardan hafifce (birkac santim) one durur ve duvara yumusak, gercekci bir temas golgesi (contact shadow) dusurur; boylece duvara yapistirilmis duz bir poster gibi degil, ince cercevesi icinde hafifce one cikan fiziksel bir nesne gibi gorunur. On yuz sahnenin isigina gore dogal ve yonlu isik alir; yuzey dumduz, golgesiz ve yapay gorunmez.`;

const R_TAHTA_YUVARLAK_FORM = `DIS FORM DAIRE (COK ONEMLI): Bu urun YUVARLAK bir baskidir; baskinin kendisi tam bir DAIREDIR - dis hatlari cember bicimindedir. Kesinlikle KARE veya DIKDORTGEN gosterme; kose YOK. Dairesel baski, onu tam cevreleyen ince dairesel (halka) bir floating cerceve icindedir; baski cerceveden tasmaz. Tasarimin dairenin disinda kalan koseleri urunun parcasi degildir, sahne arka planina karisir.`;

const R_TAHTA_PANORAMIK_FORM = function(oran){ return `DIS FORM ULTRA-GENIS PANORAMIK (${oran}) (COK ONEMLI): Bu urun ${oran} en-boy oraninda ULTRA-GENIS panoramik bir baskidir; urunun dis sinirlari bu orana BIREBIR uymalidir - genislik yukseklikten cok daha fazladir. Urunu ASLA standart bir manzara oranina (or. 3:2, 4:3, 16:9) normalize etme, sikistirma, esnetme veya farkli bir orana getirme; sahnede HER ZAMAN ${oran} ultra-genis kalir. GIRDIDEKI TASARIMIN TAMAMI GORUNMELI: verilen master tasarimin her detayi eksiksiz gorunur; kenarlardan KIRPMA veya yeniden cerceveleme yapma. Urun ince bir floating cerceve icindedir, cerceve baskiyi tam cevreler ve baski cerceveden tasmaz. SAHNE TUTARLILIGI: urunu genisligini dogal tasiyabilecek uzun yatay bir duvar alanina yerlestir. KADRAJ KARE (1:1): cikti kadraji KAREDIR; ${oran} ultra-genis urun bu karenin ICINE yerlestirilir ve ustunde/altinda bir miktar duvar bosluk kalir - bu NORMAL ve BEKLENENDIR; bu boslugu doldurmak icin urunu buyutme/uzatma, en-boy orani tam ${oran} kalir.`; };

