const TAHTA_KURALLARI_GUMUS    = R_CANVAS_KILIT + '\n\n' + R_TAHTA_CERCEVE('gumus') + '\n\n' + R_TAHTA_DOKU + '\n\n' + R_TAHTA_FOTO;
const TAHTA_KURALLARI_ANTRASIT = R_CANVAS_KILIT + '\n\n' + R_TAHTA_CERCEVE('antrasit (koyu antrasit gri)') + '\n\n' + R_TAHTA_DOKU + '\n\n' + R_TAHTA_FOTO;
