// Master -> slot atama (canvasEmit ile AYNI eslemeler; tahta kural/slot setini kullanir).
function tahtaEmit(bins, dir) {
  const d = String(dir || '').toLowerCase();
  const out = [];
  if (d.includes('yuvarlak')) {
    // Yuvarlak: cercevesiz secenek YOK. Acik renkli cerceveler (siyah/beyaz/altin/gumus/antrasit) AYNEN korunur;
    // yalnizca cercevesiz (DUZ) slotlar gumus/altin rotasyonuyla cerceveli hale getirilir.
    const bin = bins['master_yuvarlak'] ?? bins['data'];
    if (!bin) return out;
    const roundColors = ['gumus', 'altin'];
    let roundColorIdx = 0;
    const nextRoundColor = () => roundColors[roundColorIdx++ % roundColors.length];
    for (const slot of tahtaSlots) {
      let text = slot.id === 8 ? TAHTA_SAHNE_8_YUVARLAK_OZEL : slot.text;
      if (text.includes(R_TAHTA_CERCEVE_YOK)) {
        text = text.replace(R_TAHTA_CERCEVE_YOK, R_TAHTA_CERCEVE(nextRoundColor()));
      }
      out.push({ shape: 'yuvarlak', text: R_TAHTA_YUVARLAK_FORM + '\n\n' + text, bin, size: '1024x1024' });
    }
  } else if (d.includes('panoramik')) {
    const binA = bins['master_panoramik_40x20'];
    const binB = bins['master_panoramik_60x20'];
    const mapA = [1, 2, 5, 8, 9];
    const mapB = [3, 4, 6, 7, 10];
    if (binA) for (const id of mapA) { const s = tahtaSlots.find(x => x.id === id); const t = (id === 8) ? s.text : (TAHTA_PANO_OVERRIDES[id] ?? s.text); const pre = (id === 8) ? '' : (R_TAHTA_PANORAMIK_FORM('2:1') + '\n\n'); out.push({ shape: 'panoramik_40x20', text: pre + t, bin: binA, size: '1024x1024' }); }
    if (binB) for (const id of mapB) { const s = tahtaSlots.find(x => x.id === id); const t = TAHTA_PANO_OVERRIDES[id] ?? s.text; out.push({ shape: 'panoramik_60x20', text: R_TAHTA_PANORAMIK_FORM('3:1') + '\n\n' + t, bin: binB, size: '1024x1024' }); }
  } else {
    const mainKey = d.includes('dikey') ? 'master_dikey' : 'master_yatay';
    const mainBin = bins[mainKey];
    const kareBin = bins['master_kare'];
    const mainSlots = [1, 2, 3, 4, 5, 7, 9, 10];
    const kareSlots = [6, 8];
    if (mainBin) for (const id of mainSlots) { const s = tahtaSlots.find(x => x.id === id); out.push({ shape: d.includes('dikey') ? 'dikey' : 'yatay', text: s.text, bin: mainBin, size: (d.includes('dikey') ? '1024x1536' : '1536x1024') }); }
    if (kareBin) for (const id of kareSlots) {
      const text = id === 8 ? TAHTA_SAHNE_10_YATAYDIKEY_OZEL : (id === 6 ? TAHTA_SAHNE_6_KARE_OZEL : tahtaSlots.find(x => x.id === id).text);
      out.push({ shape: 'kare', text, bin: kareBin, size: '1024x1024' });
    }
  }
  return out;
}

// ── Ürün tipine + shape'e göre sahne promptları ──
function promptsFor(shape) {
  if (productType === 'glass wall art') {
    if (shape === primaryShape) return buildGlassPrimary(shape);
    return glassVariantPrompts[shape] || glassVariant;
  }
  if (productType === 'kitchen backsplash') {
    return tezgahPrompts[shape] || [];
  }
  // canvas print (master-bazli, ayri emisyon dalinda), metal wall art / printed art / mirror — ileride buraya eklenecek
  return [];
}

