// Baskili kare: kimlik 'printed panel' olur, baski kilidi ILK cumlenin hemen ardina girer
// (butcenin en guclu bolgesi), ve 'panelin kendi rengi' ibaresi dusulur - baskili panelin tek
// bir rengi yoktur. Yalniz yeni uslup kareleri (noTail) icin; eski kareler dokunulmadan kalir.

// Ince yariklarin dolmasini engelleyen cumle. Olculdu: kesim esigi 18px -> 6px (2048 ile birlikte).
// Metnin EN BASINA yakin durmali; sonda hicbir etkisi olmuyor.
function R_METAL_OPENWORK_EKLE(text){
  const C = 'Every opening is cut clean through the sheet - the narrowest hairline slits and the slits inside solid areas alike - each a true hole with the wall showing through it. The metal covers exactly what it covers in the source image and no more; every other area is open wall, never filled in.';
  if (text.indexOf('narrowest hairline slits') !== -1) return text;
  // ILK PARAGRAFIN SONUNA - kadraj tarifini bolmemek icin (m01/m02'de bolununce makro kayboldu).
  const p = text.indexOf('\n\n');
  if (p !== -1) return text.slice(0, p) + ' ' + C + text.slice(p);
  const i = text.indexOf('. ');
  return i === -1 ? C + '\n\n' + text : text.slice(0, i + 1) + ' ' + C + text.slice(i + 1);
}


// Renk emri: metnin ILK paragrafinda, openwork cumlesinin hemen ardinda.
// Siyah urunlerde uygulanmaz - kaynak tasarim zaten siyah, 'replacing the source colour' anlamsiz olur.
const METAL_RENK_BETIM = {
  'white': 'a clean bright white', 'blue': 'a deep cobalt blue', 'red': 'a deep vivid crimson',
  'silver': 'a light brushed-silver tone', 'rose gold': 'a warm brushed copper tone with a soft metallic sheen',
  'brown': 'a warm chocolate brown', 'gold': 'a rich antique gold'
};
function R_METAL_RENK_EMRI(text){
  const m = /matte ([a-z ]+?) powder coat \((#[0-9A-Fa-f]{6})\)/.exec(text)
         || /areas of this panel are ([a-z ]+?) \((#[0-9A-Fa-f]{6})\)/.exec(text);
  if (!m) return text;
  const ad = m[1].trim().toLowerCase().replace('deep matte ', '');
  const betim = METAL_RENK_BETIM[ad];
  if (!betim) return text;                       // siyah ve tanimsizlar: dokunma
  const emir = ' Recolour the metal to matte ' + ad + ' (' + m[2] + '), ' + betim +
    ': every solid part and cut edge takes this single tone, rich and saturated.' +
    ' Only the colour changes: every line and interior cut-out of the design stays exactly' +
    ' as in the source, each cut open with the wall showing through.';
  // CAPA: cumleye degil YAPIYA baglanir - ilk paragrafin sonu. (Cumleye baglayinca
  // openwork metni sikistirilinca renk emri sessizce dusmustu.)
  const p = text.indexOf('\n\n');
  return p === -1 ? text + ' ' + emir : text.slice(0, p) + emir + text.slice(p);
}


// Duvar dili + doku duzenliligi (2. canli test kusurlari; ikisi de olculdu).
const R_DUVAR_FINIS = ' plaster wall, smooth and matte with only a faint irregular hand-troweled grain';
function R_METAL_YUZEY_DUZELT(text){
  let t = text;
  t = t.replace(/,? ?finely textured plaster wall/g, ',' + R_DUVAR_FINIS);
  t = t.replace(/ textured plaster wall/g, R_DUVAR_FINIS);
  t = t.replace(/ textured wall/g, R_DUVAR_FINIS);
  t = t.replace(/a fine granular micro-texture like fine sandpaper/g,
    'an even fine granular micro-texture like fine sandpaper, uniform across the whole surface');
  t = t.replace(/A fine granular micro-texture like fine sandpaper/g,
    'An even fine granular micro-texture like fine sandpaper, uniform across the whole surface');
  return t;
}

function R_METAL_BASKI_UYARLA(text, yeniUslup){
  // 1) Sahne metnindeki renk referansi baskiyi eziyor -> notrlestirilir.
  let t = text.replace(/\bthe (white|blue|red|silver|rose gold|gold|black|brown|copper|bronze|deep matte black) product\b/g, 'the product');
  t = t.replace(/\bthe (white|blue|red|silver|rose gold|gold|black|brown|copper|bronze|deep matte black) surface\b/g, 'the surface');
  // renk iddiasi tasiyan tam cumleler atilir (orn. 'The gold reads vivid and saturated...')
  t = t.split('. ').filter(function(c){ return !/^\s*The (white|blue|red|silver|rose gold|gold|black|brown|copper|bronze|deep matte black) (reads|is|stays|looks)/.test(c); }).join('. ');
  // 2) Baskili panelin tek bir 'kendi rengi' yok.
  t = t.replace(" in the panel's own colour", '');
  const KILIT = 'Its face carries a printed artwork in full colour: every hue, gradient and pattern of the source image stays exactly as it is, saturated and true.';
  if (yeniUslup) {
    t = t.replace('this laser-cut metal wall panel', 'this full-colour printed metal wall panel');
    const i = t.indexOf('. ');
    if (i !== -1) t = t.slice(0, i + 1) + ' ' + KILIT + t.slice(i + 1);
    return t;
  }
  // Eski uslup: kilit metnin EN BASINA - butcenin en guclu bolgesi.
  return 'This is a full-colour printed metal wall panel: ' + KILIT.charAt(0).toLowerCase() + KILIT.slice(1) + '\n\n' + t;
}

